    {
      "rank": 1,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Francis Halzen",
        "Albrecht Karle",
        "Christian Spiering"
      ],
      "assessment": {
        "nobel_worthiness": "The detection of high-energy astrophysical neutrinos opened a new observational window on the universe and established neutrino astronomy as a field of lasting importance.",
        "attribution": "Halzen was central to the scientific vision and IceCube, while Karle and Spiering made major contributions to building the detector and its predecessor program. Credit across a large collaboration remains difficult.",
        "maturity": "The discovery rests on a sustained body of detections and subsequent astrophysical observations.",
        "uncertainties": [
          "The division of credit among the nominated leaders and the wider IceCube collaboration requires careful assessment."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Heino Falcke",
        "Sheperd S. Doeleman",
        "James M. Moran"
      ],
      "assessment": {
        "nobel_worthiness": "The first horizon-scale images of black holes made a striking test of strong-gravity predictions and established a powerful new observational capability.",
        "attribution": "Falcke helped develop the imaging concept, Doeleman led key technical and observational efforts, and Moran contributed to the foundational very-long-baseline interferometry program. The result depended on a global collaboration.",
        "maturity": "The images have been followed by further observations and analysis, with the method and scientific result now well established.",
        "uncertainties": [
          "The awardable contribution must be distinguished from the substantial work of the full Event Horizon Telescope collaboration."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision timekeeping and enable tests of fundamental physics as well as practical measurement applications.",
        "attribution": "Katori and Ye independently developed central approaches to trapping and cooling atoms for exceptionally precise optical clocks, making the two-person attribution strong.",
        "maturity": "The clocks have been repeatedly improved and validated, and their precision and applications have continued to develop over many years.",
        "uncertainties": [
          "The committee should weigh the original invention against later advances by many clock groups."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Frans Pretorius",
        "John G. Baker",
        "Manuela Campanelli"
      ],
      "assessment": {
        "nobel_worthiness": "Numerical relativity made reliable predictions for binary black-hole mergers possible and enabled the interpretation of gravitational-wave observations.",
        "attribution": "Pretorius achieved the breakthrough in stable simulations, followed by influential independent work from Baker and Campanelli. The selected names capture pivotal contributions across groups.",
        "maturity": "The methods have been extensively tested against gravitational-wave data and remain central to gravitational-wave astrophysics.",
        "uncertainties": [
          "The field's development involved many contributors, so the boundary of the decisive original contribution needs careful definition."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B044",
      "proposed_laureates": [
        "Fabiola Gianotti",
        "Lyn Evans",
        "Tejinder Virdee"
      ],
      "assessment": {
        "nobel_worthiness": "The experimental discovery of the Higgs boson completed a central prediction of particle physics and required extraordinary accelerator and detector performance.",
        "attribution": "Gianotti and Virdee were prominent leaders of ATLAS and CMS, while Evans led the LHC project. The discovery was independently made by two large collaborations, making individual credit unusually difficult.",
        "maturity": "The discovery was confirmed by subsequent measurements, and the particle's properties have been extensively studied.",
        "uncertainties": [
          "A Nobel-sized attribution among two collaborations and the accelerator team is unresolved.",
          "The 2013 prize recognized the theoretical prediction, which affects how a later experimental prize should be framed."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum spin Hall effect and topological insulators established a major new framework for quantum materials and stimulated broad experimental and theoretical work.",
        "attribution": "Kane and Mele provided seminal theoretical predictions, and Molenkamp's experiments demonstrated key effects in suitable materials.",
        "maturity": "The concepts have been confirmed across multiple materials and have had a durable influence on condensed-matter physics.",
        "uncertainties": [
          "The distinction between foundational theoretical work and later demonstrations, including overlap with related topological-material discoveries, needs assessment."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B031",
      "proposed_laureates": [
        "Carlton M. Caves",
        "H. Jeff Kimble",
        "Roman Schnabel"
      ],
      "assessment": {
        "nobel_worthiness": "Squeezed light enables measurements beyond the standard quantum limit and has become an important tool in precision interferometry.",
        "attribution": "Caves developed influential theoretical foundations, Kimble helped establish experimental quantum optics techniques, and Schnabel advanced squeezed-light sources and their use in gravitational-wave detectors.",
        "maturity": "The technique has moved from laboratory demonstrations into operating gravitational-wave observatories, with continued improvement.",
        "uncertainties": [
          "The contribution spans theory, pioneering experiments, and practical implementation across several groups and decades."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B042",
      "proposed_laureates": [
        "Duncan Lorimer",
        "Matthew Bailes",
        "Maura McLaughlin"
      ],
      "assessment": {
        "nobel_worthiness": "Fast radio bursts revealed a new class of energetic cosmic transients and opened a productive area of radio astronomy.",
        "attribution": "Lorimer identified the first burst, Bailes was central to the discovery and its interpretation, and McLaughlin contributed to the early work that established the phenomenon.",
        "maturity": "Many bursts have since been detected, and repeating sources and host galaxies have confirmed that the signal is a durable astrophysical phenomenon.",
        "uncertainties": [
          "The physical origins remain diverse or unsettled, and the attribution of the first discovery among the listed contributors merits careful review."
        ]
      }
    }
  ]
